#!/usr/bin/env node
// new-piece.mjs <spec.json> <out-dir> [--force] [--dry-run] [--no-fonts] [--fetch-fonts] [--selftest]
// Deterministic generator: spec -> runnable piece. No LLM, no network (except the optional font fetch). Idempotent.
// Same spec + same factory = byte-identical output. Hand-edited generated files are never overwritten without --force.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadSpec } from './lib/spec.mjs';
import { indexHtml } from './lib/html.mjs';
import { baseCss, sectionsCss } from './lib/css.mjs';
import { writePiece, sha } from './lib/manifest.mjs';
import { ensureFonts, applyFonts } from './lib/fonts.mjs';
import { WEBGL_SRC_FILES, THREE_VENDOR, MOTION_PATCH, FACTORY_VERSION } from './lib/const.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SKILLS = path.join(HERE, '..', '..');
const RUNTIME = path.join(HERE, '..', 'runtime');
const WEBGL = path.join(SKILLS, 'premium-web-webgl', 'template');
const MOTION = path.join(SKILLS, 'premium-web-motion', 'template', 'src');
const VERIFY_SECTIONS = 'main > section, footer', VERIFY_BOX = 'window.__piece && window.__piece.subject.box && window.__piece.subject.box()', VERIFY_IGNORE = '.hero-word, .foot-word, .readout';   // text that may sit over the subject: DOM wordmarks (poster fallback) and the glass readout
const BESPOKE_STUB = `// Bespoke hook: the ONE signature moment of this piece lives here (see premium-web references/wow.md).
// The factory never overwrites this file. Called once after the stage and subject are live.
// ctx = { piece, subject, stage, motion, root }  (subject is inert when WebGL is off: guard with ctx.subject.live)
export default function bespoke(ctx) {
  void ctx;
}
`;

const walk = (dir, base = dir) => fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(path.join(dir, e.name), base) : [path.relative(base, path.join(dir, e.name))]));
const read = (p) => fs.readFileSync(p);

function runtimeFiles(piece) {
  const kinds = ['glass-lattice', 'point-cloud', 'shader-field'];
  const used = new Set(piece.chapters.map((c) => c.archetype));
  return walk(RUNTIME).filter((rel) => {
    const m = rel.match(/^subjects\/(.+)\.js$/);
    if (m && kinds.includes(m[1])) return m[1] === piece.subject.kind;
    const a = rel.match(/^archetypes\/(.+)\.js$/);
    return a ? used.has(a[1]) : true;
  });
}

/** Build the full file map in memory (pure given the inputs). */
export function buildFiles(piece, outDir, fonts) {
  const files = new Map();
  const put = (rel, data, mode = 'generated') => files.set(rel, { data, mode });
  const env = { assetFor: (slot) => {
    const a = piece.assets.find((x) => x.slot === slot && x.file);
    return a && fs.existsSync(path.join(outDir, 'img', a.file)) ? { file: `img/${a.file}`, alt: a.alt || '' } : null;
  } };
  put('index.html', indexHtml(piece, env));
  put('css/base.css', baseCss(piece));
  put('css/sections.css', sectionsCss(piece));
  put('js/piece.config.js', `// Generated from the spec by new-piece.mjs. Edit the spec and regenerate; do not edit this file.\nexport const PIECE = ${JSON.stringify(clientConfig(piece), null, 2)};\n`);
  const used = [...new Set(piece.chapters.map((c) => c.archetype))];
  put('js/main.js', `// Generated. Wires the factory runtime to this piece's archetypes and its bespoke hook.\nimport { boot } from './runtime/boot.js';\nimport { PIECE } from './piece.config.js';\nimport bespoke from '../bespoke/index.js';\n${used.map((u) => `import { mount as ${u} } from './runtime/archetypes/${u}.js';`).join('\n')}\n\nboot(PIECE, { ${used.join(', ')} }, bespoke);\n`);
  for (const rel of runtimeFiles(piece)) put(`js/runtime/${rel}`, read(path.join(RUNTIME, rel)), 'copied');
  for (const f of WEBGL_SRC_FILES) put(`gl/src/${f}`, read(path.join(WEBGL, 'src', f)), 'copied');
  for (const f of THREE_VENDOR) put(`gl/vendor/${f}`, read(path.join(WEBGL, 'vendor', f)), 'copied');
  for (const rel of walk(MOTION)) {
    let data = read(path.join(MOTION, rel));
    if (rel === MOTION_PATCH.file) {
      const s = data.toString();
      if (!s.includes(MOTION_PATCH.from)) throw new Error(`motion template changed: patch anchor "${MOTION_PATCH.from}" not found in ${rel}`);
      data = s.replace(MOTION_PATCH.from, MOTION_PATCH.to);
    }
    put(`motion/src/${rel}`, data, 'copied');
  }
  put('bespoke/index.js', BESPOKE_STUB, 'user');
  put('piece.json', JSON.stringify({ verify: { sections: VERIFY_SECTIONS, subjectBox: VERIFY_BOX, ignore: VERIFY_IGNORE } }, null, 2) + '\n');   // read by premium-web/scripts/verify-piece.mjs
  put('assets.plan.json', JSON.stringify({ note: 'Slots the factory leaves to premium-web-imagery. Generate into the asset cache, then copy to img/<file> (package-piece.mjs) and regenerate.', slots: piece.assets }, null, 2) + '\n');
  if (fonts) for (const f of fonts.files) put(`fonts/${f}`, fs.readFileSync(path.join(outDir, 'fonts', f)), 'external');
  return files;
}

function clientConfig(piece) {
  const { fontFaces, fontFiles, hasFontCss, ...rest } = piece;
  void fontFaces; void fontFiles; void hasFontCss;
  return rest;
}

export function generate(specFile, outDir, { force = false, dryRun = false, fetchFonts = true, log = () => {} } = {}) {
  const t0 = performance.now();
  const { piece, warnings, spec } = loadSpec(specFile);
  warnings.forEach((w) => log(`warn: ${w}`));
  fs.mkdirSync(outDir, { recursive: true });
  const fonts = ensureFonts(outDir, piece, { fetchFonts, warn: (m) => log(`warn: ${m}`) });
  applyFonts(piece, fonts);
  const files = buildFiles(piece, outDir, fonts);
  const specHash = sha(Buffer.from(JSON.stringify(spec)));
  const report = writePiece(outDir, files, { force, dryRun, specHash });
  return { report, ms: performance.now() - t0, files: files.size, piece, factory: FACTORY_VERSION };
}

async function main() {
  const args = process.argv.slice(2), flag = (f) => args.includes(f), pos = args.filter((a) => !a.startsWith('--'));
  if (flag('--selftest')) { const { selftest } = await import('./selftest.mjs'); process.exit(await selftest()); }
  if (pos.length < 2) { console.error('usage: node new-piece.mjs <spec.json> <out-dir> [--force] [--dry-run] [--no-fonts]'); process.exit(2); }
  try {
    const r = generate(pos[0], pos[1], { force: flag('--force'), dryRun: flag('--dry-run'), fetchFonts: !flag('--no-fonts'), log: (m) => console.error(m) });
    const tally = {};
    for (const [what, rel] of r.report) { tally[what] = (tally[what] || 0) + 1; if (!['unchanged', 'kept'].includes(what) && !what.startsWith('created')) console.log(`${what}: ${rel}`); }
    console.log(`${r.piece.name}: ${r.files} files -> ${pos[1]} in ${r.ms.toFixed(0)} ms  ${JSON.stringify(tally)}`);
  } catch (e) {
    console.error(String(e.message));
    for (const [what, rel] of e.report || []) if (what.startsWith('REFUSED')) console.error(`  ${what}: ${rel}`);
    process.exit(1);
  }
}
if (process.argv[1] && fs.realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) main();
